"use server"

import { revalidatePath } from "next/cache"
import { getSession } from "@/lib/auth"
import {
  getAllUsers,
  getAllGalleriesRaw,
  saveUser,
  saveGalleries,
  saveTags,
  listTags,
  appendAudit,
  setAnnouncementBanner,
  getAnnouncementBanner,
  getAnnouncementNote,
  saveAnnouncementNote,
} from "@/lib/db"
import type { Gallery, GalleryLink, Tag, RoleName, NullReason } from "@/lib/types"
import {
  CreateGallerySchema,
  UpdateGallerySchema,
  AddLinkSchema,
  UpdateLinkSchema,
  CreateTagSchema,
  UpdateTagSchema,
  SetAnnouncementSchema,
  SaveNoteSchema,
  parseOrThrow,
} from "@/lib/validate"
import { promises as fs } from "node:fs"
import path from "node:path"

// ─── Guard ────────────────────────────────────────────────────────────────────
async function requireOwner() {
  const session = await getSession()
  if (!session?.is_owner) throw new Error("Unauthorized")
  return session
}

// ─── USER ACTIONS ─────────────────────────────────────────────────────────────

export async function adminBanUser(userId: string, reason: string) {
  const owner = await requireOwner()
  const users = await getAllUsers()
  const user = users.find((u) => u.user_id === userId)
  if (!user) throw new Error("User not found")
  if (user.user_id === owner.user_id) throw new Error("Cannot ban yourself")

  user.is_banned = true
  user.ban_reason = reason
  user.audit_log.push({
    action: "banned_by_admin",
    timestamp: new Date().toISOString(),
  })
  await saveUser(user)
  await appendAudit(owner.user_id, {
    action: `admin_ban_user:${userId}`,
    timestamp: new Date().toISOString(),
  })
  revalidatePath("/admin")
  return { ok: true }
}

export async function adminUnbanUser(userId: string) {
  const owner = await requireOwner()
  const users = await getAllUsers()
  const user = users.find((u) => u.user_id === userId)
  if (!user) throw new Error("User not found")

  user.is_banned = false
  user.ban_reason = null
  user.audit_log.push({
    action: "unbanned_by_admin",
    timestamp: new Date().toISOString(),
  })
  await saveUser(user)
  await appendAudit(owner.user_id, {
    action: `admin_unban_user:${userId}`,
    timestamp: new Date().toISOString(),
  })
  revalidatePath("/admin")
  return { ok: true }
}

export async function adminForceRoleSync(userId: string) {
  await requireOwner()
  const users = await getAllUsers()
  const user = users.find((u) => u.user_id === userId)
  if (!user) throw new Error("User not found")

  // Force cache expiry so next request triggers refresh
  user.roles_cache.cache_expires_at = new Date(0).toISOString()
  await saveUser(user)
  revalidatePath("/admin")
  return { ok: true }
}

// ─── GALLERY ACTIONS ──────────────────────────────────────────────────────────

export async function adminCreateGallery(rawData: {
  title: string
  description: string
  thumbnail: string
  tags: string[]
  minLevel: number
  minRoleName: RoleName
  isPinned: boolean
}) {
  const owner = await requireOwner()
  const data = parseOrThrow(CreateGallerySchema, rawData, "CreateGallery")
  const galleries = await getAllGalleriesRaw()

  const newGallery: Gallery = {
    id: `gallery_${Date.now()}`,
    title: data.title,
    description: data.description,
    thumbnail: data.thumbnail || "/placeholder.jpg",
    tags: data.tags,
    uploaded_by: owner.user_id,
    uploaded_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    is_active: true,
    is_pinned: data.isPinned,
    access: {
      min_hierarchy_level: data.minLevel,
      min_role_name: data.minRoleName,
      mode: "hierarchy",
    },
    stats: { total_views: 0, total_copies: 0, unique_openers: 0 },
    links: [],
  }

  galleries.push(newGallery)
  await saveGalleries(galleries)
  revalidatePath("/admin")
  revalidatePath("/")
  return { ok: true, id: newGallery.id }
}

export async function adminUpdateGallery(
  galleryId: string,
  rawData: Partial<{
    title: string
    description: string
    thumbnail: string
    tags: string[]
    is_active: boolean
    is_pinned: boolean
    minLevel: number
    minRoleName: RoleName
  }>
) {
  await requireOwner()
  const data = parseOrThrow(UpdateGallerySchema, rawData, "UpdateGallery")
  const galleries = await getAllGalleriesRaw()
  const g = galleries.find((x) => x.id === galleryId)
  if (!g) throw new Error("Gallery not found")

  if (data.title !== undefined) g.title = data.title
  if (data.description !== undefined) g.description = data.description
  if (data.thumbnail !== undefined) g.thumbnail = data.thumbnail
  if (data.tags !== undefined) g.tags = data.tags
  if (data.is_active !== undefined) g.is_active = data.is_active
  if (data.is_pinned !== undefined) g.is_pinned = data.is_pinned
  if (data.minLevel !== undefined) g.access.min_hierarchy_level = data.minLevel
  if (data.minRoleName !== undefined) g.access.min_role_name = data.minRoleName
  g.updated_at = new Date().toISOString()

  await saveGalleries(galleries)
  revalidatePath("/admin")
  revalidatePath("/")
  return { ok: true }
}

export async function adminDeleteGallery(galleryId: string) {
  await requireOwner()
  const galleries = await getAllGalleriesRaw()
  const filtered = galleries.filter((g) => g.id !== galleryId)
  if (filtered.length === galleries.length) throw new Error("Gallery not found")

  await saveGalleries(filtered)
  revalidatePath("/admin")
  revalidatePath("/")
  return { ok: true }
}

export async function adminBulkToggleGalleries(galleryIds: string[], isActive: boolean) {
  await requireOwner()
  const galleries = await getAllGalleriesRaw()
  const idSet = new Set(galleryIds)
  galleries.forEach((g) => {
    if (idSet.has(g.id)) {
      g.is_active = isActive
      g.updated_at = new Date().toISOString()
    }
  })
  await saveGalleries(galleries)
  revalidatePath("/admin")
  revalidatePath("/")
  return { ok: true }
}

export async function adminBulkDeleteGalleries(galleryIds: string[]) {
  await requireOwner()
  const galleries = await getAllGalleriesRaw()
  const idSet = new Set(galleryIds)
  const filtered = galleries.filter((g) => !idSet.has(g.id))
  await saveGalleries(filtered)
  revalidatePath("/admin")
  revalidatePath("/")
  return { ok: true }
}

// ─── LINK ACTIONS ─────────────────────────────────────────────────────────────

export async function adminAddLink(
  galleryId: string,
  rawData: {
    label: string
    url: string
    copyLimit: number
    minLevel: number
  }
) {
  await requireOwner()
  const data = parseOrThrow(AddLinkSchema, rawData, "AddLink")
  const galleries = await getAllGalleriesRaw()
  const g = galleries.find((x) => x.id === galleryId)
  if (!g) throw new Error("Gallery not found")

  const newLink: GalleryLink = {
    id: `link_${Date.now()}`,
    label: data.label,
    url: data.url,
    is_active: true,
    null_reason: null,
    copy_limit_per_user: data.copyLimit,
    total_copies: 0,
    accessible_by_min_level: data.minLevel,
  }

  g.links.push(newLink)
  g.updated_at = new Date().toISOString()
  await saveGalleries(galleries)
  revalidatePath("/admin")
  revalidatePath("/")
  return { ok: true, id: newLink.id }
}

export async function adminUpdateLink(
  galleryId: string,
  linkId: string,
  rawData: Partial<{
    label: string
    url: string
    is_active: boolean
    null_reason: NullReason
    copy_limit_per_user: number
    accessible_by_min_level: number
  }>
) {
  await requireOwner()
  const data = parseOrThrow(UpdateLinkSchema, rawData, "UpdateLink")
  const galleries = await getAllGalleriesRaw()
  const g = galleries.find((x) => x.id === galleryId)
  if (!g) throw new Error("Gallery not found")
  const link = g.links.find((l) => l.id === linkId)
  if (!link) throw new Error("Link not found")

  Object.assign(link, data)
  g.updated_at = new Date().toISOString()
  await saveGalleries(galleries)
  revalidatePath("/admin")
  revalidatePath("/")
  return { ok: true }
}

export async function adminDeleteLink(galleryId: string, linkId: string) {
  await requireOwner()
  const galleries = await getAllGalleriesRaw()
  const g = galleries.find((x) => x.id === galleryId)
  if (!g) throw new Error("Gallery not found")
  g.links = g.links.filter((l) => l.id !== linkId)
  g.updated_at = new Date().toISOString()
  await saveGalleries(galleries)
  revalidatePath("/admin")
  revalidatePath("/")
  return { ok: true }
}

// ─── TAG ACTIONS ──────────────────────────────────────────────────────────────

export async function adminCreateTag(rawData: {
  name: string
  display: string
  color: string
}) {
  const owner = await requireOwner()
  const data = parseOrThrow(CreateTagSchema, rawData, "CreateTag")
  const tags = await listTags()

  if (tags.find((t) => t.name === data.name)) {
    throw new Error("Tag name already exists")
  }

  const newTag: Tag = {
    id: `tag_${Date.now()}`,
    name: data.name,
    display: data.display,
    color: data.color,
    gallery_ids: [],
    gallery_count: 0,
    created_at: new Date().toISOString(),
    created_by: owner.user_id,
    is_active: true,
  }

  const updated = [...tags, newTag]
  await saveTags(updated)
  revalidatePath("/admin")
  revalidatePath("/")
  return { ok: true, id: newTag.id }
}

export async function adminUpdateTag(
  tagId: string,
  rawData: Partial<{ name: string; display: string; color: string; is_active: boolean }>
) {
  await requireOwner()
  const data = parseOrThrow(UpdateTagSchema, rawData, "UpdateTag")
  const tags = await listTags()
  const t = tags.find((x) => x.id === tagId)
  if (!t) throw new Error("Tag not found")
  Object.assign(t, data)
  await saveTags(tags)
  revalidatePath("/admin")
  revalidatePath("/")
  return { ok: true }
}

export async function adminDeleteTag(tagId: string) {
  await requireOwner()
  const [tags, galleries] = await Promise.all([listTags(), getAllGalleriesRaw()])

  // Remove tag from all galleries
  galleries.forEach((g) => {
    g.tags = g.tags.filter((id) => id !== tagId)
  })

  const updatedTags = tags.filter((t) => t.id !== tagId)
  await Promise.all([saveTags(updatedTags), saveGalleries(galleries)])
  revalidatePath("/admin")
  revalidatePath("/")
  return { ok: true }
}

// ─── ANNOUNCEMENT BANNER ──────────────────────────────────────────────────────

export async function adminSetAnnouncement(message: string, type: "info" | "warning" | "success" | null) {
  await requireOwner()
  const data = parseOrThrow(SetAnnouncementSchema, { message, type }, "SetAnnouncement")
  await setAnnouncementBanner(
    data.message && data.type ? { message: data.message, type: data.type, created_at: new Date().toISOString() } : null
  )
  revalidatePath("/")
  revalidatePath("/admin")
  return { ok: true }
}

// ─── BACKUP & RESTORE ─────────────────────────────────────────────────────────

export async function adminCreateBackup() {
  await requireOwner()
  const DB_DIR = path.join(process.cwd(), "database")

  const [users, galleries, tags] = await Promise.all([
    fs.readFile(path.join(DB_DIR, "users.json"), "utf-8"),
    fs.readFile(path.join(DB_DIR, "gallery.json"), "utf-8"),
    fs.readFile(path.join(DB_DIR, "tag.json"), "utf-8"),
  ])

  const snapshot = {
    snapshot_at: new Date().toISOString(),
    version: "1.0",
    users: JSON.parse(users),
    galleries: JSON.parse(galleries),
    tags: JSON.parse(tags),
  }

  return { ok: true, data: JSON.stringify(snapshot, null, 2) }
}

export async function adminResetStats(galleryId: string) {
  await requireOwner()
  const galleries = await getAllGalleriesRaw()
  const g = galleries.find((x) => x.id === galleryId)
  if (!g) throw new Error("Gallery not found")
  g.stats = { total_views: 0, total_copies: 0, unique_openers: 0 }
  g.links.forEach((l) => (l.total_copies = 0))
  await saveGalleries(galleries)
  revalidatePath("/admin")
  return { ok: true }
}
// ─── NOTE ACTIONS ─────────────────────────────────────────────────────────────

export async function adminGetNote() {
  await requireOwner()
  const note = await getAnnouncementNote()
  return { ok: true, note }
}

export async function adminSaveNote(contentHtml: string, contentText: string) {
  const owner = await requireOwner()
  const data = parseOrThrow(SaveNoteSchema, { contentHtml, contentText }, "SaveNote")
  await saveAnnouncementNote({
    content_html: data.contentHtml,
    content_text: data.contentText,
    updated_at: new Date().toISOString(),
    updated_by: owner.user_id,
  })
  revalidatePath("/")
  revalidatePath("/admin")
  return { ok: true }
}